// The tab handoff bundle: shipping's tab-import-handoff.js, unchanged, for
// the sandboxed runner (docs/superpowers/specs/2026-11-16-fork-tab-handoff-design.md).
// It never loads Sync, settings, Electron, filesystem or account modules.
//   node chromium/tools/build-handoff-bundle.mjs [--check]
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import {execFileSync} from 'node:child_process';
import {fileURLToPath} from 'node:url';
const root=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'../..');
const runner=path.join(root,'chromium/blanc/services/sync_runner');
// The shipping release the module is read from.
export const HANDOFF_TAG='v1.49.1';
const MODULE='src/main/tab-import-handoff.js';
const SHIMS=['handoff-crypto','handoff'];
const EXTERNAL={'node:crypto':'handoff-crypto'};
const literal=v=>JSON.stringify(v).replace(/[<>\u2028\u2029]/g,c=>`\\u${c.charCodeAt(0).toString(16).padStart(4,'0')}`);
export function handoffBundle(tag=HANDOFF_TAG){
 const source=execFileSync('git',['-C',root,'show',`${tag}:${MODULE}`],{encoding:'utf8',maxBuffer:4e6});
 const map={};
 for(const [,name] of source.matchAll(/require\(\s*['"]([^'"]+)['"]\s*\)/g)){
  if(!EXTERNAL[name])throw Error('Unaudited handoff dependency: '+name);
  map[name]=`shim:${EXTERNAL[name]}`;
 }
 const shim=name=>fs.readFileSync(path.join(runner,'shims',name+'.js'),'utf8');
 const entries=SHIMS.map(name=>`${literal('shim:'+name)}:[function(module,exports,require){\n${shim(name)}\n},{}]`);
 entries.push(`${literal(MODULE)}:[function(module,exports,require){\n${source}\n},${literal(map)}]`);
 return `// Generated by chromium/tools/build-handoff-bundle.mjs from ${tag}. Don't edit.
${shim('prelude')}
(function(g){'use strict';const M={${entries.join(',\n')}};const C={};
function load(id){if(C[id])return C[id].exports;const e=M[id];if(!e)throw Error('no module '+id);const m=C[id]={exports:{}};
e[0](m,m.exports,r=>{const t=e[1][r];if(!t)throw Error('no require '+r+' in '+id);return load(t)});return m.exports}
g.__require=load;})(globalThis);
globalThis.__call=(method,argsJson,done)=>{try{if(method!=='desktop.handoff')throw Error('forbidden');
Promise.resolve(__require('shim:handoff')(...JSON.parse(argsJson))).then(value=>done(true,JSON.stringify(value)),error=>done(false,String(error&&error.message||error)));
}catch(error){done(false,String(error.message||error));}};
`;
}
export const hashHandoff=text=>crypto.createHash('sha256').update(text).digest('hex');
if(process.argv[1]===fileURLToPath(import.meta.url)){
 const text=handoffBundle(),hash=hashHandoff(text);
 const files={'generated/handoff-bundle.js':text,'handoff_bundle_hash.h':`// Generated by chromium/tools/build-handoff-bundle.mjs. Don't edit.\n#ifndef BLANC_SERVICES_SYNC_RUNNER_HANDOFF_BUNDLE_HASH_H_\n#define BLANC_SERVICES_SYNC_RUNNER_HANDOFF_BUNDLE_HASH_H_\nnamespace blanc {\ninline constexpr char kBlancHandoffBundleSha256[] = "${hash}";\n}\n#endif\n`};
 for(const [name,bytes] of Object.entries(files)){const file=path.join(runner,name);if(process.argv.includes('--check')){if(fs.readFileSync(file,'utf8')!==bytes)throw Error('Handoff bundle is stale: '+name);}else fs.writeFileSync(file,bytes);}
 console.log(`${HANDOFF_TAG}: handoff ${text.length} bytes, ${hash}`);
}
